text:
{
 "lead": {
  "es": "外国《がいこく》にある日本《にほん》の大使館《たいしかん》など（在外公館《ざいがいこうかん》）の場所《ばしょ》の書《か》き方《かた》を変《か》える法律《ほうりつ》です。そこで働《はたら》く外務公務員《がいむこうむいん》（外務省《がいむしょう》の職員《しょくいん》）の手当《てあて》を変《か》えたり、新《あたら》しくつくったりします。",
  "hs": "在外公館（海外の大使館など）の位置の表記を改め、在外公館で働く外務公務員の手当を改定したり、新しく設けたりする法律。"
 },
 "facts/0/text": {
  "es": "ラトビアにある日本《にほん》大使館《たいしかん》の場所《ばしょ》の地名《ちめい》を変《か》えます。外国《がいこく》で働《はたら》く人《ひと》の基本《きほん》の手当《てあて》（在勤《ざいきん》基本手当《きほんてあて》）の、もとになる額《がく》を変《か》えます。配偶者《はいぐうしゃ》（夫《おっと》や妻《つま》）の手当《てあて》を見直《みなお》します。",
  "hs": "在ラトビア日本国大使館の位置の地名を改める。在勤基本手当（海外勤務の基本の手当）の基準額を改定し、配偶者手当《はいぐうしゃてあて》を見直す。"
 },
 "facts/1/text": {
  "es": "いっしょに外国《がいこく》へ行《い》く子《こ》どもの手当《てあて》（同行《どうこう》子女《しじょ》手当《てあて》）を新《あたら》しくつくります。家族《かぞく》をおいて一人《ひとり》で外国《がいこく》で働《はたら》く人《ひと》の手当《てあて》（在外《ざいがい》単身赴任手当《たんしんふにんてあて》）も新《あたら》しくつくります。日本《にほん》にのこした家《いえ》の住《す》まいの手当《てあて》をはらいます。子《こ》どもの教育《きょういく》の手当《てあて》で、幼稚園《ようちえん》にあたるところの上乗《うわの》せの、いちばん高《たか》い額《がく》を変《か》えます。",
  "hs": "同行子女手当（子どもを連れて行く人の手当）と在外｜単身赴任手当《たんしんふにんてあて》（家族と離《はな》れて｜1人《ひとり》で赴任《ふにん》する人の手当）を新設し、国内の留守宅の住居手当を支給する。子女教育手当のうち、幼稚園《ようちえん》にあたる施設《しせつ》についての加算額の限度額を改定する。"
 },
 "facts/2/text": {
  "es": "この法律《ほうりつ》が使《つか》われ始《はじ》める日《ひ》（施行《しこう》）は、令和《れいわ》8年《ねん》4月《がつ》｜1日《ついたち》です。",
  "hs": "施行《しこう》（法律が実際に効力をもつこと）は令和8年4月1日。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、次《つぎ》のことをふまえています。世界《せかい》のようすが変《か》わったことです。外国《がいこく》の大使館《たいしかん》などへ、一人《ひとり》で働《はたら》きに行《い》く人《ひと》がふえたことです。外国《がいこく》で働《はたら》く外務公務員《がいむこうむいん》の、行《い》き方《かた》がいろいろになったことです。そこで、ラトビアにある日本《にほん》大使館《たいしかん》の場所《ばしょ》の地名《ちめい》を変《か》えることが必要《ひつよう》だ、としています。在勤《ざいきん》基本手当《きほんてあて》の、もとになる額《がく》を変《か》えることも必要《ひつよう》だ、としています。配偶者《はいぐうしゃ》の手当《てあて》の見直《みなお》しや、同行《どうこう》子女《しじょ》手当《てあて》と在外《ざいがい》単身赴任手当《たんしんふにんてあて》を新《あたら》しくつくることなども必要《ひつよう》だ、としています。",
  "hs": "内閣は、国際情勢の変化や、在外公館への単身赴任《たんしんふにん》の増加など、在外公館で働く外務公務員の赴任《ふにん》の形が多様になっていることをふまえています。そのうえで、在ラトビア日本国大使館の位置の地名を改め、在勤基本手当の基準額の改定、配偶者手当《はいぐうしゃてあて》の見直し、同行子女手当と在外｜単身赴任手当《たんしんふにんてあて》の新設などの措置《そち》（対応）が必要だとしている。"
 },
 "more/who/text": {
  "es": "外国《がいこく》の大使館《たいしかん》などで働《はたら》く外務公務員《がいむこうむいん》と、その家族《かぞく》です。家族《かぞく》には、配偶者《はいぐうしゃ》や、いっしょに行《い》く子《こ》どもなどがいます。",
  "hs": "在外公館（海外の大使館など）で働く外務公務員と、その配偶者《はいぐうしゃ》や同行する子どもなどの家族。"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》の外務委員会《がいむいいんかい》と参議院《さんぎいん》の外交防衛委員会《がいこうぼうえいいいんかい》は、どちらも全員《ぜんいん》の賛成《さんせい》で決《き》めました（全会一致《ぜんかいいっち》）。もとの案《あん》のとおりです。参議院《さんぎいん》では、外国《がいこく》で働《はたら》く職員《しょくいん》の給料《きゅうりょう》や手当《てあて》のあり方《かた》について質問《しつもん》がありました。配偶者《はいぐうしゃ》の手当《てあて》を見直《みなお》すわけなども聞《き》かれました。",
  "hs": "衆議院外務委員会と参議院外交防衛委員会は、どちらも全会一致《ぜんかいいっち》（全員の賛成）で原案どおり可決した。参議院では、在外職員の給与《きゅうよ》や手当のあり方、配偶者手当《はいぐうしゃてあて》を見直す理由などについて質疑があった。"
 }
}
